import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{C as t,E as n,M as r,N as i,O as a,P as o,S as s,_ as c,a as l,b as u,j as d,k as f,l as p,n as m,o as h,t as g,u as _,w as v}from"./shared-JA1PGxXr.js";import{t as y}from"./file-text-BJyuJnB_.js";import{t as b}from"./key-round-Ce2aNFPL.js";import{t as x}from"./CodeEditor-DqHMt3P8.js";var S=e();function C({module:e}){return(0,S.jsxs)(i,{children:[(0,S.jsx)(r,{variant:`project`,chip:e??`Месяц 2 · Блок 8`,title:`Сценарий Planner`,intro:`Проверим готовый Planner от команды до JSON-файла и обратно. Сначала запишем ожидаемый результат, затем сравним его с сообщением CLI, состоянием задачи и сохранёнными данными.`,tags:[{icon:(0,S.jsx)(y,{size:14}),label:`сквозная приёмка`},{icon:(0,S.jsx)(b,{size:14}),label:`состояние и сохранение`}]}),(0,S.jsxs)(o,{number:`00`,title:`От проверенных частей к одному пользовательскому пути`,children:[(0,S.jsx)(a,{children:`Команда «завершить задачу» может показать успех, хотя после повторной загрузки задача снова открыта. Значит, одного правильного сообщения недостаточно. Сегодня проверим весь путь действия: ввод, изменение задачи, запись в файл и повторное чтение.`}),(0,S.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`По маршруту 39.2 уже подготовлены Task, PlannerService, оба storage, CLI и проверки. Перед работой убедимся, что они есть в нашей копии проекта.`},{title:`Новый вопрос`,description:`Совпадают ли пользовательский ответ, состояние задач и сохранённые данные на успешном и ошибочном пути?`},{title:`Результат`,description:`Мы проводим приёмку на отдельном JSON, восстанавливаем состояние новым сервисом и исправляем только подтверждённый дефект.`}]}),(0,S.jsx)(`p`,{children:`Сначала откроем свою текущую версию проекта. Найдём Task, PlannerService, MemoryStorage, JsonStorage, функцию execute_command и тесты модели, сервиса, хранения и CLI. Если компонент отсутствует, зафиксируем пробел и вернёмся к соответствующему предыдущему занятию. Номер урока сам по себе не доказывает, что файл или тест уже существует.`})]}),(0,S.jsxs)(o,{number:`01`,title:`Что именно мы проверяем`,children:[(0,S.jsx)(a,{children:`Сквозная проверка проходит через несколько готовых частей программы одним пользовательским действием. Если тест Task проходит, мы знаем что-то о модели. Но пока не знаем, вызывает ли команда нужный метод сервиса и попадает ли результат на диск.`}),(0,S.jsx)(`p`,{children:`Возьмём независимый пример с заметкой. Кнопка сообщает «сохранено», текст виден в открытом окне, но после нового открытия исчезает. Проверка кнопки и проверка текстового поля по отдельности не показали бы такую ошибку. С Planner поступим так же: сравним ответ CLI, значение Task в памяти и содержимое учебного JSON. Эти три наблюдения отвечают на разные вопросы.`}),(0,S.jsx)(f,{items:[{title:`1. Сообщение`,description:`CLI отвечает «выполнено». Мы знаем, что обработчик сформировал ответ, но пока не знаем, записалось ли изменение.`},{title:`2. Объект`,description:`У Task свойство is_done равно True. Теперь изменение видно в памяти, но файл ещё может содержать False.`},{title:`3. Файл`,description:`В JSON сохранён выполненный статус. Затем новый сервис должен загрузить его обратно в новую Task.`}]}),(0,S.jsx)(`p`,{children:`До первой команды запишем прогноз сразу для всех трёх точек. Дополнительная проверка новым сервисом нужна потому, что даже корректный JSON ещё не доказывает правильную загрузку. Для операций чтения, например list, сообщение меняется, но состояние Task и файл должны оставаться прежними.`}),(0,S.jsx)(u,{question:`CLI ответил «задача выполнена», а в файле осталось is_done: false. Что подтверждено?`,options:[`Команда дала ответ, но сохранение результата не подтверждено`,`Состояние точно восстановится после нового запуска`,`Проверка успешна, ведь CLI показал правильную строку`],correctIndex:0,explanation:`Мы нашли расхождение между сообщением и диском. Теперь посмотрим на Task в памяти и место вызова save; по одному сообщению нельзя объявить сценарий успешным.`})]}),(0,S.jsxs)(o,{number:`02`,title:`Роли объектов в одном сценарии`,children:[(0,S.jsx)(a,{children:`Перед проверкой восстановим роли. Модель Task хранит данные одной задачи и её правила. Сервис PlannerService решает, что сделать с набором задач. CLI принимает текст и показывает ответ, а storage загружает и сохраняет данные.`}),(0,S.jsxs)(g,{caption:`Команда, сервис и путь сохранённых данных`,children:[(0,S.jsxs)(h,{label:`Связь CLI, PlannerService, storage и JSON-файла`,children:[(0,S.jsx)(p,{title:`CLI`,shape:`process`}),(0,S.jsx)(m,{label:`вызов и ответ`,direction:`both`}),(0,S.jsx)(p,{title:`PlannerService`}),(0,S.jsx)(l,{forward:`save: сервис → storage`,reverse:`load: storage → сервис`}),(0,S.jsx)(p,{title:`JSON storage`}),(0,S.jsx)(l,{forward:`запись JSON`,reverse:`чтение JSON`}),(0,S.jsx)(p,{title:`JSON-файл`,shape:`database`})]}),(0,S.jsx)(_,{title:`Граница ответственности`,children:(0,S.jsx)(`p`,{children:`Task меняет собственный статус, сервис выбирает операцию, storage работает с сохранением. В памяти и в JSON могут временно находиться разные значения, поэтому их сравниваем отдельно.`})})]}),(0,S.jsx)(`p`,{children:`Проследим команду done для задачи №1. CLI передаёт запрос сервису; сервис находит нужную Task, меняет статус через подготовленную операцию и при действительном изменении вызывает сохранение. После этого CLI формирует ответ. Метод чтения не должен по дороге вызывать save. При неизвестном ID менять список также нечего.`}),(0,S.jsx)(`p`,{children:`JSON является текстовым форматом хранения: в нём есть словари, списки и простые значения, но нет методов объектов Python. Task.to_dict() создаёт словарь из полей задачи, а Task.from_dict() собирает новую задачу из такого словаря. JsonStorage записывает и читает этот формат. Точные ключи берём из нашей готовой модели, новые поля для приёмки не придумываем.`}),(0,S.jsx)(x,{caption:`Один и тот же статус на разных границах, схема`,code:`CLI: done 1 → сообщение о завершении
Task в памяти: id=1, is_done=True
to_dict(): словарь с теми же полями
JsonStorage: save → учебный файл
новый JsonStorage: load → from_dict() → новая Task`}),(0,S.jsx)(`p`,{children:`MemoryStorage работает с задачами в памяти, а JsonStorage сохраняет их в файл. Оба подчиняются знакомому договору load/save, но опыт только с MemoryStorage не докажет сохранение на диск. Передача готового storage в PlannerService называется композицией: сервис использует другой объект, не наследуя его класс.`}),(0,S.jsx)(s,{statement:`Если Task.is_done равен True в первом сервисе, второй сервис обязательно загрузит True из JSON.`,isTrue:!1,explanation:`Мы видим только состояние первого объекта. Между ним и новым объектом должны успешно пройти save, файл, load и восстановление Task.`})]}),(0,S.jsxs)(o,{number:`03`,title:`От отдельных тестов к сквозному сценарию`,children:[(0,S.jsx)(a,{children:`Тест компонента проверяет конкретное правило. Например, тест Task проверяет перевод в словарь; тест сервиса проверяет изменение статуса; тест JsonStorage проверяет запись и чтение файла. Сквозной сценарий объединяет их с настоящей командой CLI.`}),(0,S.jsx)(`p`,{children:`Представим, что JsonStorage умеет правильно сохранять список, но CLI подключён к другому экземпляру сервиса. Все небольшие тесты могут быть зелёными, а пользовательская команда изменяет совсем другой набор. Поэтому заранее выпишем начальное состояние, ожидаемый ответ, итоговую Task и содержимое файла для каждого шага.`}),(0,S.jsx)(x,{caption:`Шаблон наблюдения после одной команды`,code:`КОМАНДА: done 1 (синтаксис уточняем в своём CLI)
ДО: Task №1 открыта, в JSON is_done=false
ОЖИДАЕМ: ответ об изменении → Task №1 выполнена → JSON обновлён
ПОЛУЧИЛИ: записываем каждое фактическое значение
РАСХОЖДЕНИЕ: указываем первую неверную точку`}),(0,S.jsx)(`p`,{children:`Если сначала читать файл, а потом придумывать ожидаемый результат, легко принять ошибку за норму. Мы действуем наоборот: прогноз до команды, наблюдение после неё. При успешной записи файл меняется; после list, get, search или stats файл остаётся тем же и лишний save не вызывается.`}),(0,S.jsx)(`p`,{children:`Например, после добавления двух задач команда search возвращает №2. Это подтверждает поиск, но не сохранение. Если JSON всё ещё пустой, первая точка расхождения находится между результатом действия и записью в файл. А если JSON содержит №2, но новый сервис её не видит, проверяем путь загрузки. Так одинаковый внешний симптом может привести к разным местам поиска. Мы не меняем весь сервис только потому, что один экран показал неверный результат.`}),(0,S.jsx)(u,{question:`Модель и JsonStorage прошли свои тесты. Что ещё требуется для сквозной проверки?`,options:[`Выполнить команду через настоящий CLI и сопоставить ответ, Task и файл`,`Ещё раз вызвать только Task.to_dict()`,`Посмотреть сообщение CLI, не открывая сохранённые данные`],correctIndex:0,explanation:`Отдельные тесты проверяют детали. Команда через CLI проверяет правильность соединения обработчика, сервиса, модели и storage.`})]}),(0,S.jsxs)(o,{number:`04`,title:`Положительный путь через настоящий CLI`,children:[(0,S.jsx)(a,{children:`Проверяем готовый CLI на отдельном учебном JSON. Если JsonStorage требует существующий файл, создаём пустую структуру в его штатном формате; если сам обрабатывает отсутствующий путь, начинаем без файла. Рабочие данные программы не затрагиваем.`}),(0,S.jsx)(`p`,{children:`Заранее запишем ожидаемую картину: добавляем «Позвонить» под ID 1 и «Купить тетрадь» под ID 2. Обе задачи открыты. Затем вызываем list, get второй задачи и search по слову «тетрадь». Мы используем синтаксис своего готового CLI, а не выдумываем новые команды или параметры.`}),(0,S.jsx)(`p`,{children:`После каждого добавления сравним сообщение, полученные Task и две записи файла. Читающие команды должны найти существующие данные, но не изменить ни объект, ни JSON и не вызвать save. Это важно: даже правильный список на экране не оправдывает незаметную запись на диск при каждом просмотре.`}),(0,S.jsx)(v,{title:`Восстановим порядок контрольного сценария`,prompt:`Расположите действия от исходного JSON до наблюдаемого итога.`,pieces:[{id:`empty`,code:`пустой учебный JSON`,note:`Мы начинаем с пустого учебного файла.`},{id:`add`,code:`add двух задач`,note:`Получаем id 1 и 2 и две открытые Task.`},{id:`read`,code:`list → get → search`,note:`Убеждаемся, что чтение не меняет файл.`},{id:`change`,code:`done №1 → delete №2`,note:`Остаётся одна выполненная Task с id 1.`},{id:`stats`,code:`stats`,note:`Ожидаем всего 1, выполнено 1, открыто 0.`}],correctOrder:[`empty`,`add`,`read`,`change`,`stats`],explanation:`Мы начинаем с известной базы, затем различаем чтение и изменения и только после этого сверяем итоговую сводку.`,incorrectExplanation:`Мы восстановим причинный порядок: сначала зафиксируем исходные данные, затем изменения и в конце ожидаемый результат.`}),(0,S.jsx)(`p`,{children:`Когда задача №1 завершена, а №2 удалена, остаётся ровно одна выполненная задача с прежним ID 1. Статистика даёт всего 1, выполнено 1, открыто 0. Удаление не меняет номер оставшейся Task: ID принадлежит объекту, а не позиции в списке.`}),(0,S.jsx)(`p`,{children:`Следующий ID здесь вычисляется по принятому правилу max(существующие ID) + 1: после удаления максимальный номер равен 1, значит новый будет 2. Повторное использование удалённого ID разрешено этим договором. Для проверки добавления используем копию учебного файла, чтобы не испортить контрольный финал.`}),(0,S.jsx)(c,{code:`tasks = [
    {"id": 1, "is_done": False},
    {"id": 2, "is_done": False},
]
tasks[0]["is_done"] = True
tasks.pop(1)
all_count = len(tasks)
done_count = sum(task["is_done"] for task in tasks)
open_count = all_count - done_count
print(all_count, open_count, done_count)`,output:`1 0 1`,hint:`Сначала изменим признак у первой задачи, затем удалим вторую запись. Статистика считает оставшийся список, а не число введённых команд.`}),(0,S.jsxs)(n,{tone:`info`,children:[(0,S.jsx)(`strong`,{children:`Контрольная точка.`}),` Совпали ли ответ CLI, Task и JSON после каждой мутации? После чтения убедимся в отсутствии записи. Только затем переходим к новому экземпляру сервиса.`]})]}),(0,S.jsxs)(o,{number:`05`,title:`Восстановление новым сервисом`,children:[(0,S.jsx)(a,{children:`Первый сервис уже содержит Task в памяти. Чтобы проверить именно файл, создадим новый JsonStorage с прежним путём и передадим его другому, новому PlannerService. Старые списки и объекты ему не передаём.`}),(0,S.jsx)(`p`,{children:`Сначала убедимся, что второй сервис действительно смотрит в тот же учебный JSON. Затем через готовые методы получим список и stats. Ожидаем только Task №1 со статусом «выполнена» и числа 1/1/0: всего / выполнено / открыто. Это уже проверка чтения сохранённого результата, а не только повторного обращения к старому объекту.`}),(0,S.jsxs)(g,{caption:`Новое восстановление читает тот же файл, но создаёт новые объекты`,children:[(0,S.jsxs)(h,{label:`Два сервиса соединены только путём к учебному файлу`,children:[(0,S.jsx)(p,{title:`Сервис A`}),(0,S.jsx)(m,{label:`save`}),(0,S.jsx)(p,{title:`учебный JSON`,shape:`database`}),(0,S.jsx)(m,{label:`load`}),(0,S.jsx)(p,{title:`Сервис B`})]}),(0,S.jsx)(_,{title:`Что мы исключили`,children:(0,S.jsx)(`p`,{children:`Сервис B не получил список из памяти A. Если задача появилась в B с верным статусом, она прошла через сохранённый файл и восстановление.`})})]}),(0,S.jsx)(`p`,{children:`Для следующего добавления прогнозируем ID 2 и проверяем его только на копии файла. Если второй сервис видит две задачи или первую открытой, прежде всего сверим путь, JSON и момент load(), а не будем переписывать Task. Экземпляр означает отдельный объект класса, процесс означает отдельный запуск программы. Мы создали второй объект в текущем процессе; проверку нового процесса, README и Git проведём в 40.1.`}),(0,S.jsx)(u,{question:`Что подтверждает новый PlannerService на том же JSON-пути?`,options:[`Что данные снова загружаются через storage, а не берутся из прежнего сервиса`,`Что отдельный процесс и чистый клон уже проверены`,`Что любая неудачная запись автоматически откатила память`],correctIndex:0,explanation:`Новый сервис проверяет повторное чтение на том же пути. Новый процесс и чистая копия дают отдельные доказательства.`})]}),(0,S.jsxs)(o,{number:`06`,title:`Ошибки, состояние и границы гарантий`,children:[(0,S.jsx)(a,{children:`Отказной сценарий проверяет, что программа делает при неправильном запросе или недоступном файле. Для каждого случая берём отдельную копию JSON с одной выполненной задачей №1, чтобы ошибки не влияли друг на друга.`}),(0,S.jsx)(`p`,{children:`Проверим неверный формат ID, неизвестный ID, неизвестную команду и повторное done уже выполненной №1. Запишем сообщение, состояние Task, содержимое JSON и число вызовов save. Неизвестный ID не создаёт новую задачу, а повторное завершение не добавляет нового изменения. Если CLI после ошибки запрашивает исправленный ввод и действие всё же успешно, ожидаем одно сохранение от успешного изменения.`}),(0,S.jsx)(`p`,{children:`Сбой чтения и сбой записи проверяем раздельно. Повреждённый существующий JSON нельзя незаметно заменить пустым списком или перезаписать. При неудачной записи программа не должна объявлять данные успешно сохранёнными. Но объект Task в памяти мог успеть измениться: гарантия отката зависит от прежнего договора сервиса.`}),(0,S.jsx)(x,{caption:`Два отказа и разные гарантии, схема наблюдений`,code:`неизвестный ID → отказ → Task прежняя → save не вызван
storage.save: ошибка → файл: проверяем отдельно
                         память: проверяем отдельно
storage.load: ошибка → не подменяем файл пустыми данными`}),(0,S.jsx)(s,{statement:`Если save завершился ошибкой, состояние Task в памяти гарантированно вернулось к исходному.`,isTrue:!1,explanation:`Мы не обещаем автоматический rollback: объект уже мог измениться до вызова storage. Проверяем отдельно состояние памяти и факт успешной записи.`}),(0,S.jsx)(`p`,{children:`Мы не будем обещать «ничего не изменилось», пока не проверили каждый слой. При ошибке сохранения обычная файловая запись может даже оставить частично изменённый файл; нужно увидеть фактическое состояние на копии. Вывод по отказу формулируем точно: какая операция завершилась ошибкой, что осталось в памяти и что прочитано с диска.`})]}),(0,S.jsxs)(o,{number:`07`,title:`Локализуем дефект и закрепляем исправление`,children:[(0,S.jsx)(a,{children:`Допустим, после done CLI сообщил успех, а второй сервис прочитал прежний статус. Это воспроизводимый дефект: ожидание и наблюдение расходятся. Прежде чем менять код, повторим ситуацию с тем же начальным JSON и найдём первую неверную границу.`}),(0,S.jsx)(`p`,{children:`Если Task в памяти уже выполнена, а файл нет, посмотрим на вызов save и выбранный storage. Если изменился файл, а второй сервис видит прежнюю задачу, сверим путь и загрузку. Если ошибка ввода поменяла задачу, проверим, когда началось изменение относительно проверки аргумента. Так мы ищем причину без замены всего проекта.`}),(0,S.jsx)(t,{code:`# фрагмент: service и storage уже созданы
task = service.get_task(1)
task.mark_done()
restored = storage.load()
assert restored[0].is_done is True`,question:`Почему эта проверка может падать, хотя mark_done изменил Task?`,options:[`Изменение объекта обошло сервисный путь и не было сохранено через service`,`is_done нельзя читать после загрузки JSON`,`Любой load() автоматически сбрасывает все статусы`],correctIndex:0,explanation:`В примере мы обошли сервисную операцию: изменение в памяти не обязано попасть в JSON. В действующем Planner используем предусмотренную операцию service.mark_done(1), которая организует изменение и сохранение.`,fix:`service.mark_done(1)
restored = storage.load()
assert restored[0].is_done is True`}),(0,S.jsx)(`p`,{children:`В этом учебном фрагменте мы обошли сервис и изменили модель напрямую. Исправление возвращает работу на предусмотренный маршрут. Если в настоящем проекте ошибка другая, не копируем исправление из карточки: сначала убеждаемся, что наш тест воспроизводит именно её.`}),(0,S.jsxs)(n,{tone:`info`,children:[(0,S.jsx)(`strong`,{children:`Правило приёмки.`}),` Если расхождения нет, оставляем рабочий код без изменений. Если оно найдено, сначала закрепляем воспроизведение тестом и только потом исправляем причину.`]}),(0,S.jsx)(`p`,{children:`Регрессионный тест фиксирует конкретное ожидание, чтобы ошибка не вернулась после правки. Мы сохраняем исходные данные, точную команду, ожидание и фактический результат. Тест должен не проходить на дефектной версии, а после адресного исправления проходить без специальных обходов.`}),(0,S.jsx)(`p`,{children:`После исправления повторим спорный путь и запустим полный pytest: модель, сервис, storage и CLI. Если каких-то тестов предыдущих уроков в копии нет, перечислим недостачу; один зелёный test_cli.py нельзя назвать полным набором. Если расхождений нет, фиксируем результаты сценария и оставляем код без искусственного коммита.`}),(0,S.jsx)(x,{caption:`эскиз разбора, не запускаемый код`,code:`повторить точное действие
сверить сообщение, Task и storage
найти первую неверную границу
закрепить наблюдение тестом
исправить причину и повторить сценарий`}),(0,S.jsx)(`p`,{children:`Для каждого найденного дефекта укажем первый шаг, на котором ожидаемое и фактическое поведение разошлись. В тесте зафиксируем наблюдаемое условие, например статус задачи после загрузки вторым сервисом, вместо проверки внутреннего порядка вызовов без необходимости. После исправления повторим прежний отрицательный случай: он особенно важен, потому что исправленная успешная команда может незаметно начать сохранять файл даже при ошибке ввода.`})]}),(0,S.jsxs)(o,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,S.jsx)(a,{children:`Практика соединит уже изученные роли и проверки. Мы используем действующий Persistent Planner и отдельный учебный JSON; этот шаг не начинает проект с модели или пустого CLI.`}),(0,S.jsx)(f,{variant:`connected`,items:[{title:`Сверим вход`,description:`Мы подтвердим Task, service, оба storage, CLI и тесты предыдущих занятий, включая 39.2. Недостающие части не будем создавать заново в финальной приёмке.`},{title:`Пройдём сценарий`,description:`Мы выполним add, list, find, search, done, delete и stats; сообщения, поля, статусы и записи должны совпасть.`},{title:`Восстановим данные`,description:`Мы создадим новый service на том же JSON-пути и сверим список, завершённость, сводку и следующий id.`},{title:`Разберём отказы`,description:`Мы проверим ошибки и вызовы save на копии; воспроизводимый дефект получит узкий тест и исправление, а чистый проход не вызовет косметических изменений.`}]}),(0,S.jsx)(`p`,{children:`Схема ролей подготовила нас к выбору места проверки: CLI отвечает за сообщение, сервис за действие, модель за правила Task, storage за актуальные данные. Мы сверим три наблюдения вместе, чтобы успешный вывод не скрыл несохранённое изменение.`}),(0,S.jsx)(`p`,{children:`Новый service подтверждает восстановление через выбранный путь. Отдельный процесс, чистая копия, README и передача проверенной версии остаются следующим шагом. Здесь мы завершаем сквозную приёмку уже готового продукта.`}),(0,S.jsx)(d,{text:`Пройдите сквозной сценарий на учебном JSON и исправьте только воспроизводимое расхождение.`})]})]})}export{C as Lesson40};